/**
 * The shared brain of the daily poke — the parts the browser and the dispatch function must
 * never disagree about: what the notification says, where it opens, and when a subscription
 * is due. This file is the source of truth; `scripts/sync-push-core.mjs` copies it verbatim
 * into `supabase/functions/push-dispatch/`, the same arrangement the companion prompts use.
 * It must therefore stay free of imports and browser APIs — plain TypeScript and `Intl` only.
 *
 * The copy rule lives here so it can be tested: a notification is read on a lock screen, by
 * whoever is holding the phone. It says the day's Gospel is ready and nothing more — nothing
 * tender, nothing personal, ever. The depth waits inside the app.
 */

export const PUSH_TITLE = 'Sanctum';
export const PUSH_BODY = 'Your Gospel and reflection are ready.';

/**
 * The vocabulary of reminder focuses — the same vocabulary as the email reminder.
 * Since Erik's ruling of Nov 16, 2026 the daily reminder has exactly ONE landing (the
 * day's Gospel — see FOCUS_ROUTES and deepLinkUrlForFocus below); the other three
 * legacy keys survive only so subscriptions and links created before the ruling still
 * parse. Nov 18, 2026 added four landing-only keys for the newer pokes — 'mass',
 * 'confession', 'drivehome', 'tailor'. They are never a subscription's stored daily
 * focus (the database still constrains that column to the legacy four); they exist
 * so those pokes' taps land where their words promise.
 */
export const PUSH_FOCUS_KEYS = ['gospel', 'examen', 'rosary', 'rule', 'mass', 'confession', 'drivehome', 'tailor'] as const;
export type PushFocus = (typeof PUSH_FOCUS_KEYS)[number];
export const DEFAULT_PUSH_FOCUS: PushFocus = 'gospel';

export function isPushFocus(value: unknown): value is PushFocus {
  return typeof value === 'string' && (PUSH_FOCUS_KEYS as readonly string[]).includes(value);
}

/**
 * Where a tap on the notification lands. Erik's ruling (Nov 16, 2026): the reminder has
 * one landing — the day's Gospel on Today. The notification's own words promise the
 * Gospel ("Your Gospel and reflection are ready"), so every focus, including the three
 * legacy keys kept for old subscriptions, resolves to the same route. A focus that
 * cannot resolve to a real screen would be a broken promise, so the map stays total
 * over the four keys and tests pin it.
 */
export interface FocusRoute {
  tab: 'today' | 'church';
  churchTab?: string;
  /** Inside the Pray door: which section opens. */
  churchPray?: string;
  /** Land on Today with the Tonight closing revealed, even outside the evening hours. */
  todayExamen?: boolean;
  /** Land on Today with the Gospel card's Tailor panel open. */
  todayTailor?: boolean;
}

export const FOCUS_ROUTES: Record<PushFocus, FocusRoute> = {
  gospel: { tab: 'today' },
  examen: { tab: 'today' },
  rosary: { tab: 'today' },
  rule: { tab: 'today' },
  mass: { tab: 'today' },
  confession: { tab: 'church', churchTab: 'confession' },
  // The drive-home poke's landing changed with its purpose (Nov 20, 2026):
  // it once opened Tonight, to close the day on the ride home; now it
  // sends the man to the Tailor build, to make his devotional for the road.
  drivehome: { tab: 'today', todayTailor: true },
  tailor: { tab: 'today', todayTailor: true },
};

/**
 * The URL the notification opens. The daily reminder has one landing since
 * Nov 16, 2026: the Gospel, carrying the `#daily-gospel` fragment the Today
 * screen honours by scrolling the readings into view — whatever legacy focus
 * an old subscription still holds, this is where its tap goes. The newer
 * pokes (Nov 18, 2026) carry their own landings: the Mass poke also points
 * at the Gospel (the readings are what a man takes to Mass), the Confession
 * poke opens Pocket Church's Confession door, and the tailor-ready poke
 * opens the Tailor panel. The drive-home poke's URL still carries its own
 * focus — its slot, its marker — but since Nov 20, 2026 the route it
 * resolves to is the Tailor panel: the poke now sends a man to tailor his
 * devotional for the drive home, so its tap lands where its words promise.
 */
export function deepLinkUrlForFocus(focus: string): string {
  switch (focus) {
    case 'mass':
      return '/?focus=mass#daily-gospel';
    case 'confession':
      return '/?focus=confession';
    case 'drivehome':
      return '/?focus=drivehome';
    case 'tailor':
      return '/?focus=tailor';
    default:
      return '/?focus=gospel#daily-gospel';
  }
}

export interface PushPayload {
  title: string;
  body: string;
  url: string;
  focus: PushFocus;
}

/**
 * The newer pokes' fixed words (Nov 18, 2026) — as fixed as the daily
 * poke's: a lock screen is a public place, so each says what is coming and
 * nothing personal, ever. The Mass and Confession pokes name no parish
 * (the server has never been told it); the tailor-ready poke names no
 * content of the build it announces. The drive-home poke is the one poke
 * with a title of its own (Nov 20, 2026): it no longer closes the day —
 * it sends the man to tailor his devotional for the road — and its words
 * say exactly that, and nothing about where he is going or why.
 */
export const MASS_PUSH_BODY = 'Mass at your parish is coming up.';
export const CONFESSION_PUSH_BODY = 'Confession time at your parish is coming up.';
export const DRIVE_HOME_PUSH_TITLE = 'The drive home';
export const DRIVE_HOME_PUSH_BODY = 'Tailor your devotional for the road.';
export const TAILOR_READY_PUSH_BODY = 'Your tailored devotional is ready to listen to.';

const SLOT_PUSH_TITLES: Partial<Record<PushFocus, string>> = {
  drivehome: DRIVE_HOME_PUSH_TITLE,
};

const SLOT_PUSH_BODIES: Partial<Record<PushFocus, string>> = {
  mass: MASS_PUSH_BODY,
  confession: CONFESSION_PUSH_BODY,
  drivehome: DRIVE_HOME_PUSH_BODY,
  tailor: TAILOR_READY_PUSH_BODY,
};

/** Builds exactly what the service worker is allowed to show. No other text ever ships. */
export function buildPushPayload(focus: string): PushPayload {
  const safe: PushFocus = isPushFocus(focus) ? focus : DEFAULT_PUSH_FOCUS;
  return { title: SLOT_PUSH_TITLES[safe] ?? PUSH_TITLE, body: SLOT_PUSH_BODIES[safe] ?? PUSH_BODY, url: deepLinkUrlForFocus(safe), focus: safe };
}

/** Reads the focus out of a page URL's query string (`?focus=examen`); null when absent or unknown. */
export function parseFocusParam(search: string): PushFocus | null {
  try {
    const value = new URLSearchParams(search).get('focus');
    return isPushFocus(value) ? value : null;
  } catch {
    return null;
  }
}

/** A reminder time is always 'HH:MM', 24-hour — the shape an <input type="time"> produces. */
export function isValidLocalTime(value: unknown): value is string {
  return typeof value === 'string' && /^([01]\d|2[0-3]):[0-5]\d$/.test(value);
}

export function localTimeToMinutes(localTime: string): number {
  const [h, m] = localTime.split(':').map((part) => Number(part));
  return h * 60 + m;
}

/** The dispatch cron runs every quarter hour; a poke is due inside one quarter-hour window. */
export const DISPATCH_WINDOW_MINUTES = 15;

export interface PushSubscriptionTiming {
  tz: string;
  /** 'HH:MM', the subscriber's chosen local time. */
  localTime: string;
  /** 'YYYY-MM-DD' in the subscriber's timezone — the local date of the last delivered poke. */
  lastSentOn: string | null;
}

export interface LocalNow {
  dateKey: string;
  minutes: number;
}

/** What the wall clock in `tz` says right now: the local date, and minutes since local midnight. */
export function localNowParts(now: Date, tz: string): LocalNow {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: tz,
    hourCycle: 'h23',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  }).formatToParts(now);

  const get = (type: string) => parts.find((p) => p.type === type)?.value ?? '';
  const hour = Number(get('hour')) % 24; // h23 can still report 24 at midnight in some engines
  return {
    dateKey: `${get('year')}-${get('month')}-${get('day')}`,
    minutes: hour * 60 + Number(get('minute')),
  };
}

function shiftDateKey(dateKey: string, days: number): string {
  const [y, m, d] = dateKey.split('-').map((part) => Number(part));
  const shifted = new Date(Date.UTC(y, m - 1, d) + days * 86_400_000);
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${shifted.getUTCFullYear()}-${pad(shifted.getUTCMonth() + 1)}-${pad(shifted.getUTCDate())}`;
}

export interface DueEvaluation {
  due: boolean;
  /** The local date this poke belongs to — what gets written to `last_sent_on` on delivery. */
  localDateKey: string;
}

/**
 * Is this subscription owed a poke on this dispatch tick?
 *
 * Due when the chosen local time fell inside the last quarter hour and no poke has been
 * delivered for that local date yet. The arithmetic is done in minutes-of-day, modulo a
 * day, so a 23:55 reminder caught by the 00:05 tick still fires — and belongs to the date
 * its time fell on, which the wrap branch recovers by stepping the date back one day.
 *
 * Daylight saving is handled by the `lastSentOn` guard rather than by the clock math:
 * on the autumn fall-back day a 1:30 reminder's local time happens twice, but the second
 * occurrence finds the date already marked sent. On the spring-forward day a 2:30 reminder
 * never falls inside any window (that hour does not exist) and is simply skipped — one
 * missed poke in a year, by design, rather than a poke at a wrong-feeling hour.
 */
export function evaluateDue(sub: PushSubscriptionTiming, now: Date): DueEvaluation {
  if (!isValidLocalTime(sub.localTime)) return { due: false, localDateKey: '' };
  let local: LocalNow;
  try {
    local = localNowParts(now, sub.tz);
  } catch {
    return { due: false, localDateKey: '' }; // an unparseable timezone never sends
  }

  const target = localTimeToMinutes(sub.localTime);
  const sinceTarget = (local.minutes - target + 1440) % 1440;
  if (sinceTarget >= DISPATCH_WINDOW_MINUTES) {
    return { due: false, localDateKey: local.dateKey };
  }

  const targetDateKey = local.minutes >= target ? local.dateKey : shiftDateKey(local.dateKey, -1);
  return { due: sub.lastSentOn !== targetDateKey, localDateKey: targetDateKey };
}

export function isDue(sub: PushSubscriptionTiming, now: Date): boolean {
  return evaluateDue(sub, now).due;
}

/**
 * The evening slot (Erik's ruling, Nov 17, 2026): a subscriber may add a
 * second daily poke in the evening. It is the SAME poke — same payload, same
 * Gospel landing — so the only new question is when it is due, and that is
 * the morning question asked of the evening hour, with the evening slot's
 * own sent marker. Two guards keep it honest:
 *
 * - No evening hour set (or a malformed one) means no evening poke, ever.
 * - An evening hour equal to the morning hour is one poke, never two
 *   identical ones minutes apart in spirit and seconds apart in fact.
 */
export interface PushEveningTiming extends PushSubscriptionTiming {
  /** 'HH:MM', the optional evening hour; null when no evening reminder is set. */
  eveningTime: string | null;
  /** 'YYYY-MM-DD' in the subscriber's timezone — the local date of the last delivered evening poke. */
  eveningLastSentOn: string | null;
}

export function evaluateEveningDue(sub: PushEveningTiming, now: Date): DueEvaluation {
  if (!isValidLocalTime(sub.eveningTime)) return { due: false, localDateKey: '' };
  if (sub.eveningTime === sub.localTime) return { due: false, localDateKey: '' };
  return evaluateDue(
    { tz: sub.tz, localTime: sub.eveningTime, lastSentOn: sub.eveningLastSentOn },
    now,
  );
}

export function isEveningDue(sub: PushEveningTiming, now: Date): boolean {
  return evaluateEveningDue(sub, now).due;
}

/** The day of week (0 = Sunday … 6 = Saturday) of a local calendar date — a property of the date itself, not of any timezone. */
function dayOfWeekOfDateKey(dateKey: string): number {
  const [y, m, d] = dateKey.split('-').map((part) => Number(part));
  return new Date(Date.UTC(y, m - 1, d)).getUTCDay();
}

/** Whole days since the epoch for a local calendar date — the ruler the weekly math measures on. */
function dateKeyToDayIndex(dateKey: string): number {
  const [y, m, d] = dateKey.split('-').map((part) => Number(part));
  return Math.floor(Date.UTC(y, m - 1, d) / 86_400_000);
}

/** How long after the event itself a weekly poke may still land — a late tick is a nudge, not a post-mortem. */
export const WEEKLY_GRACE_MINUTES = 30;

/**
 * Is a weekly poke owed on this dispatch tick? (The parish Mass and
 * Confession reminders, Erik, Nov 18, 2026.)
 *
 * The event is a weekly local datetime — a day of week and an 'HH:MM' in
 * the subscription's timezone — and the poke belongs to the moment `leadMin`
 * minutes BEFORE it. That moment may fall on the previous local date (an
 * early Mass with a two-hour lead is reminded the night before), so the
 * arithmetic is done in absolute local minutes: the local date read as a
 * day index, times 1440, plus the wall-clock minutes. Both occurrences
 * that could own this tick — the most recent event day and the next one —
 * are tested, and the poke is due from the reminder moment until half an
 * hour past the event itself.
 *
 * The returned `localDateKey` is the EVENT's local date — the date written
 * to the slot's sent marker — so the guard is per event, not per day the
 * poke happened to land on. Daylight saving is handled the way the daily
 * slots handle it: everything is compared in local wall-clock terms, and
 * the marker refuses a duplicate.
 */
export function evaluateWeeklyDue(
  now: Date,
  timeZone: string,
  dayOfWeek: number,
  timeHHMM: string,
  leadMin: number,
  lastSentOn: string | null,
): DueEvaluation {
  if (!Number.isInteger(dayOfWeek) || dayOfWeek < 0 || dayOfWeek > 6) return { due: false, localDateKey: '' };
  if (!isValidLocalTime(timeHHMM)) return { due: false, localDateKey: '' };
  if (!Number.isInteger(leadMin) || leadMin <= 0 || leadMin > 1440) return { due: false, localDateKey: '' };
  let local: LocalNow;
  try {
    local = localNowParts(now, timeZone);
  } catch {
    return { due: false, localDateKey: '' }; // an unparseable timezone never sends
  }

  const todayIndex = dateKeyToDayIndex(local.dateKey);
  const nowAbs = todayIndex * 1440 + local.minutes;
  const eventMinutes = localTimeToMinutes(timeHHMM);
  const daysBack = (dayOfWeekOfDateKey(local.dateKey) - dayOfWeek + 7) % 7;

  for (const eventIndex of [todayIndex - daysBack, todayIndex - daysBack + 7]) {
    const eventAbs = eventIndex * 1440 + eventMinutes;
    if (nowAbs >= eventAbs - leadMin && nowAbs < eventAbs + WEEKLY_GRACE_MINUTES) {
      const eventDateKey = shiftDateKey(local.dateKey, eventIndex - todayIndex);
      return { due: lastSentOn !== eventDateKey, localDateKey: eventDateKey };
    }
  }
  return { due: false, localDateKey: local.dateKey };
}

export function isWeeklyDue(
  now: Date,
  timeZone: string,
  dayOfWeek: number,
  timeHHMM: string,
  leadMin: number,
  lastSentOn: string | null,
): boolean {
  return evaluateWeeklyDue(now, timeZone, dayOfWeek, timeHHMM, leadMin, lastSentOn).due;
}

/**
 * The Confession "evening before" lead (Erik, Nov 20, 2026): instead of a
 * count of minutes before the Confession hour, one poke at 7:00 PM local
 * on the day BEFORE the parish's Confession day — the night to examine,
 * before the morning to confess. Lead-minutes arithmetic cannot express
 * it, so the lead travels as a SENTINEL: conf_lead_min = -1, accepted by
 * the sync RPC only for Confession, and special-cased here and in the
 * dispatcher. It is never passed to evaluateWeeklyDue (whose own guard
 * refuses a lead of zero or less, so even a wiring mistake cannot turn
 * the sentinel into a time).
 *
 * Due inside the same quarter-hour window as the daily slots, asked of
 * 19:00 on the eve. The returned `localDateKey` is the CONFESSION day's
 * date — the same marker the minutes leads write — so the slot's dedupe
 * is per Confession day across lead choices: a man who changes his lead
 * midweek is never poked twice for the same Confession. The Confession
 * hour itself plays no part: the eve is fixed by the day alone. 7 PM
 * exists on both daylight-saving transition days (the jumps happen at
 * 2 AM), so no hour is ever skipped or doubled; the marker stands guard
 * regardless.
 */
export const CONFESSION_EVENING_BEFORE_LEAD = -1;
export const CONFESSION_EVENING_BEFORE_TIME = '19:00';

export function evaluateConfessionEveDue(
  now: Date,
  timeZone: string,
  confDay: number,
  lastSentOn: string | null,
): DueEvaluation {
  if (!Number.isInteger(confDay) || confDay < 0 || confDay > 6) return { due: false, localDateKey: '' };
  let local: LocalNow;
  try {
    local = localNowParts(now, timeZone);
  } catch {
    return { due: false, localDateKey: '' }; // an unparseable timezone never sends
  }

  const target = localTimeToMinutes(CONFESSION_EVENING_BEFORE_TIME);
  const sinceTarget = (local.minutes - target + 1440) % 1440;
  if (sinceTarget >= DISPATCH_WINDOW_MINUTES) {
    return { due: false, localDateKey: local.dateKey };
  }

  // Inside the window the wall clock is between 19:00 and 19:14, so the
  // evening in question is today's; the Confession day it belongs to is
  // tomorrow's date — which must be the parish's Confession day.
  const confessionDateKey = shiftDateKey(local.dateKey, 1);
  if (dayOfWeekOfDateKey(confessionDateKey) !== confDay) {
    return { due: false, localDateKey: local.dateKey };
  }
  return { due: lastSentOn !== confessionDateKey, localDateKey: confessionDateKey };
}

export function isConfessionEveDue(
  now: Date,
  timeZone: string,
  confDay: number,
  lastSentOn: string | null,
): boolean {
  return evaluateConfessionEveDue(now, timeZone, confDay, lastSentOn).due;
}

/**
 * The drive-home slot (Erik, Nov 18, 2026): a third daily poke at its own
 * hour. It opened Tonight at first; since Nov 20, 2026 it sends the man
 * to tailor his devotional for the drive home, and its tap opens the
 * Tailor build. Due-matching is unchanged — the daily question asked of
 * the drive hour with the drive slot's own marker — and deliberately
 * WITHOUT the morning/evening pair's same-time guard: slots of different
 * purposes are independent, so a drive hour that happens to equal the
 * evening hour still fires for its own reason.
 */
export interface PushDriveTiming extends PushSubscriptionTiming {
  /** 'HH:MM', the optional drive-home hour; null when no drive-home reminder is set. */
  driveTime: string | null;
  /** 'YYYY-MM-DD' in the subscriber's timezone — the local date of the last delivered drive-home poke. */
  driveLastSentOn: string | null;
}

export function evaluateDriveDue(sub: PushDriveTiming, now: Date): DueEvaluation {
  if (!isValidLocalTime(sub.driveTime)) return { due: false, localDateKey: '' };
  return evaluateDue(
    { tz: sub.tz, localTime: sub.driveTime, lastSentOn: sub.driveLastSentOn },
    now,
  );
}

export function isDriveDue(sub: PushDriveTiming, now: Date): boolean {
  return evaluateDriveDue(sub, now).due;
}
